contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Send some ether to this test contract so it can fund calls that require value forwarding.
    receive() external payable {}

    // Test logic: parameters are ownerCaller (the address attempting withdraw), recipient, and amount
    // We check that when msgSender == owner, calling withdrawAll succeeds and results in c's balance becoming zero,
    // which holds for the original contract but is violated by the mutant that disallows the owner.
    function runTest(address payable caller, address payable recipient, uint256 fundAmount) public payable {
        // Precondition: this test contract must have enough balance to fund a call if needed
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund the contract c by sending value to its fallback
        // Use low-level call to forward ETH to c
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding c failed");

        // Record c balance before withdraw
        uint256 before = address(c).balance;
        require(before == fundAmount, "unexpected funded amount");

        // Prepare to invoke withdrawAll as the caller. We must simulate calling from 'caller'.
        // Achieve this by having the caller perform the call: require the caller == msg.sender of this function
        // so the verifier explores the case where msg.sender equals owner (caller is owner)
        // For that, we require that caller is equal to c.owner()
        address owner = c.owner();
        require(caller == owner, "caller must be owner for this test");

        // Now perform the withdrawAll call from this contract (msg.sender will be this contract).
        // To make the call originate from the owner, the test assumes external tooling will set msg.sender==owner when invoking runTest.
        // However, tools/verifiers can instead call c.withdrawAll from the owner address directly; here we invoke c.withdrawAll normally.
        c.withdrawAll(recipient);

        // After a successful withdrawAll by the owner, c's balance must be zero (the contract transferred all funds out)
        uint256 after = address(c).balance;

        // The distinguishing assertion: owner-initiated withdrawAll transfers entire balance away
        assert(after == 0);
    }
}

