    function run(address caller, address recipient) public payable {
        // We will call withdrawAll expecting that non-owners cannot call it.
        // Ensure the call is made from the provided caller by using a low-level call to c.withdrawAll
        // Note: we cannot change msg.sender in Solidity directly, so we use a proxy pattern via address(c).call
        // However, per constraints we must call c.withdrawAll as a top-level call; instead, require that caller is not the owner by observing c.owner() — owner() is public.
        // Precondition: caller is not the owner of c
        require(c.owner() != caller);

        // Make the call from this contract (msg.sender == this contract). To reflect the intended general rule,
        // we treat `reverted` as whether the call from a non-owner reverts when invoked by msg.sender != owner.
        // The public function withdrawAll uses msg.sender to compare with owner; in this test our msg.sender is this contract,
        // so ensure this contract is not the owner as well.
        require(c.owner() != address(this));

        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }

        // Assert that when the caller is not the owner (here, this contract is not owner), the call reverts.
        assert(reverted == true);
    }
    receive() external payable {}
}

