    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller and recipient and initial balance to send to c
    function testFuzz_property(address caller, address recipient, uint256 seedAmount) public {
        // keep addresses wide but non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        // bound amount to avoid overflow issues but allow zero
        uint256 amount = bound(seedAmount, 0, 1 ether);

        // Fund the caller so they can send ETH to the contract
        vm.deal(caller, amount + 1 wei);

        // Have caller send amount to c so c has balance to withdraw
        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        // the above call is the fallback payable; it should succeed for EOAs
        require(sent);

        // Decide who will call withdrawAll: fuzzed 'caller' will call withdrawAll
        // We want to check the universal property: when the caller is the owner, withdrawAll should succeed on the reference; when not, it should revert (or not transfer).
        // The test performs the call and observes whether it succeeded and whether the contract balance became zero.

        bool ok;
        // perform withdrawAll as 'caller' and catch revert by try/catch pattern
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (single assertion): On the correct contract, only the owner can successfully withdraw the contract balance.
        // We observe this by asserting that (ok == (caller == address(this))) implies the contract balance is zero when ok is true.
        // But we must make a single assertTrue reading c. We encode the property as: if the call succeeded then caller must be owner and contract balance is zero; if the call failed then either caller wasn't owner or balance unchanged.

        // To express a single universal boolean about c that the reference satisfies for all inputs and the mutant violates for some,
        // we assert: (ok == (caller == address(this))) && (ok ? address(c).balance == 0 : (address(c).balance == amount))
        // However assertTrue must read c and be a single assert. Build the boolean accordingly.

        bool property = false;
        if (ok) {
            // if call succeeded, caller must be owner and contract balance must be zero
            property = (caller == address(this)) && (address(c).balance == 0);
        } else {
            // if call failed, either caller wasn't owner and contract balance unchanged
            property = (caller != address(this)) && (address(c).balance == amount);
        }

        // single assertion that the reference contract always satisfies and the mutant will violate for some inputs
        assertTrue(property);
    }
}

