        initBalance = bound(initBalance, 0, 1 ether);

        // Fund contract with initBalance
        if (initBalance > 0) {
            vm.deal(address(this), initBalance);
            // send funds from owner (address(this)) to contract
            payable(address(c)).transfer(initBalance);
        }

        // Act as nonOwner and call withdrawAll(recipient)
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): for any non-owner caller, the contract's balance must remain equal to initial balance
        // The correct contract satisfies this for all inputs; the mutant that transfers before require can make the balance decrease
        assertTrue(address(c).balance == initBalance);
    }
}

