pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule: For any caller who is NOT owner and any recipient that REVERTs on receive,
    // calling withdrawAll(recipient) on the correct contract will NOT revert (it will simply perform the require and return),
    // whereas the mutant that transfers before checking owner will attempt the transfer first and therefore will revert.
    // We fuzz the caller address (as an EOA) and the amount seeded into the contract to ensure there is a non-zero balance.
    function testFuzz_property(address caller, uint256 seedAmount) public {
        // keep domain wide but meaningful
        vm.assume(caller != address(0));
        vm.assume(caller != address(this)); // ensure not the owner
        // ensure contract has some positive balance to attempt transfer
        uint256 amount = bound(seedAmount, 1, 1 ether);
        // fund the contract
        vm.deal(address(this), amount);
        // send ether into c so it has balance
        c.withdrawAll{value: 0}(address(this)); // no-op but ensures compilation; then fund directly
        (bool sent,) = address(c).call{value: amount}('');
        require(sent);

        // deploy a recipient that always reverts on receive; this models an adversarial counterparty
        Reverter recv = new Reverter();

        // The caller we fuzzed is an EOA (no code) — but we need to simulate a non-owner caller invoking withdrawAll.
        // Use vm.prank to make the call originate from the fuzzed caller.
        vm.prank(caller);

        // Call withdrawAll; capture whether it reverts. The correct contract does the owner check first and should NOT attempt transfer,
        // so it should return (ok == true). The mutant that transfers first will cause the call to revert when recipient rejects funds (ok == false).
        bool ok;
        try c.withdrawAll(address(recv)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the property: for this non-owner caller and a reverting recipient, the correct contract always returns (does not revert).
        // This assertion is true for the reference and will be violated by the mutant for some inputs (the fuzzer will find such a caller and seedAmount).
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("no peeking");
    }
    receive() external payable {
        revert("nope");
    }
}
